package org.apache.commons.math.stat.descriptive.moment;

import org.apache.commons.lang3.builder.EqualsBuilder;
import org.junit.*;
import static org.junit.Assert.*;

public class VarianceSymflowerTest {
	@Test
	public void clear1() {
		Variance v = new Variance();
		v.clear();
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void clear2() {
		Variance v = new Variance();
		v.incMoment = true;
		v.clear();
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void evaluate3() {
		Variance v = new Variance();
		double[] values = null;
		double[] weights = null;
		v.evaluate(values, weights);
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void evaluate4() {
		Variance v = new Variance();
		double[] values = null;
		double mean = Double.NaN;
		v.evaluate(values, mean);
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void evaluate5() {
		Variance v = new Variance();
		double[] values = null;
		double[] weights = null;
		double mean = Double.NaN;
		v.evaluate(values, weights, mean);
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void getN6() {
		Variance v = new Variance();
		v.getN();
	}

	@Test
	public void getN7() {
		Variance v = new Variance();
		v.moment = new SecondMoment();
		v.moment.dev = 0.;
		v.moment.m1 = 0.;
		v.moment.m2 = 0.;
		v.moment.nDev = 0.;
		long expected = 0L;
		long actual = v.getN();

		assertEquals(expected, actual);

		Variance vExpected = new Variance();
		vExpected.moment = new SecondMoment();
		vExpected.moment.dev = 0.;
		vExpected.moment.m1 = 0.;
		vExpected.moment.m2 = 0.;
		vExpected.moment.nDev = 0.;

		assertTrue(EqualsBuilder.reflectionEquals(vExpected, v, false, null, true));
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void getResult8() {
		Variance v = new Variance();
		v.getResult();
	}

	@Test
	public void getResult9() {
		Variance v = new Variance();
		v.moment = new SecondMoment();
		v.moment.dev = 0.;
		v.moment.m1 = 0.;
		v.moment.m2 = 0.;
		v.moment.n = 1L;
		v.moment.nDev = 0.;
		double expected = 0.0D;
		double actual = v.getResult();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getResult10() {
		Variance v = new Variance();
		v.moment = new SecondMoment();
		v.moment.dev = 0.;
		v.moment.m1 = 0.;
		v.moment.m2 = 0.;
		v.moment.n = 4L;
		v.moment.nDev = 0.;
		double expected = 0.0D;
		double actual = v.getResult();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getResult11() {
		Variance v = new Variance();
		v.setBiasCorrected(true);
		v.moment = new SecondMoment();
		v.moment.dev = 0.;
		v.moment.m1 = 0.;
		v.moment.m2 = 0.;
		v.moment.n = 4L;
		v.moment.nDev = 0.;
		double expected = 0.0D;
		double actual = v.getResult();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void increment12() {
		Variance v = new Variance();
		double d = Double.NaN;
		v.increment(d);
	}

	@Test // (expected = java.lang.NullPointerException.class)
	public void increment13() {
		Variance v = new Variance();
		v.incMoment = true;
		double d = Double.NaN;
		v.increment(d);
	}

	@Test
	public void isBiasCorrected14() {
		Variance v = new Variance();
		boolean actual = v.isBiasCorrected();

		assertFalse(actual);
	}

	@Test
	public void setBiasCorrected15() {
		Variance v = new Variance();
		boolean biasCorrected = false;
		v.setBiasCorrected(biasCorrected);

		Variance vExpected = new Variance();

		assertTrue(EqualsBuilder.reflectionEquals(vExpected, v, false, null, true));
	}
}
